# ICommand 接口
public interface ICommand
{
    bool CanExecute(object? p);
    void Execute(object? p);
    event EventHandler? CanExecuteChanged;
}

# 一个通用 RelayCommand 实现
public class RelayCommand(Action<object?> ex,
                          Func<object?, bool>? can = null) : ICommand
{
    public bool CanExecute(object? p) => can == null || can(p);
    public void Execute(object? p) => ex(p);
    public event EventHandler? CanExecuteChanged;
}
