# OnRender 自绘画布(进度环/图表)
public class Ring : FrameworkElement
{
    protected override void OnRender(DrawingContext dc)
    {
        var r = ActualWidth / 2;
        dc.DrawEllipse(null,
            new Pen(Brushes.Gray, 12),
            new Point(r, r), r - 6, r - 6);
        // 绘制圆角弧表示进度
        var figure = new PathFigure(new Point(r, 6),
            new[] { new ArcSegment(new Point(r, ActualHeight - 6),
                       new Size(r, r), 180, false, SweepDirection.Clockwise, true) },
            true);
        dc.DrawGeometry(null, new Pen(Brushes.DodgerBlue, 12),
            new PathGeometry(new[] { figure }));
    }
}
# (每改值调 InvalidateVisual() 重绘)

